import Foundation

// MARK: - The labelled corpus format (NL-AUTO-25)

/// A labelled drawing corpus for the automation benchmark: where the symbols are, which rooms a
/// click should trace and to what area, what each sheet is called and at what scale it is drawn.
///
/// Two corpora share this format. The **synthetic** one is generated by
/// ``AutomationSyntheticCorpus`` and lives in git as code: door symbols attached to walls, hatch,
/// text drawn as strokes, dimension chains, rooms with door openings, title blocks in two
/// languages. A **local** corpus is real drawings that stay on the machine that runs it, outside
/// git, described by a JSON file in this format and named by the `ZENIT_AUTOMATION_CORPUS`
/// environment variable. Synthetic-only calibration failed on the first real plan once (LT-15);
/// the second corpus exists so that cannot happen silently again.
public struct AutomationCorpusManifest: Codable, Hashable, Sendable {
    public var name: String
    public var drawings: [AutomationCorpusDrawing]

    public init(name: String, drawings: [AutomationCorpusDrawing]) {
        self.name = name
        self.drawings = drawings
    }

    /// Reads a manifest; relative drawing paths resolve against the manifest's directory.
    public static func load(from url: URL) throws -> (manifest: AutomationCorpusManifest, baseDirectory: URL) {
        let data = try Data(contentsOf: url)
        let manifest = try JSONDecoder().decode(AutomationCorpusManifest.self, from: data)
        return (manifest, url.deletingLastPathComponent())
    }

    public func encoded() throws -> Data {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        return try encoder.encode(self)
    }
}

public struct AutomationCorpusDrawing: Codable, Hashable, Sendable {
    /// Path to the PDF, relative to the manifest's directory (or absolute).
    public var file: String
    public var pages: [AutomationCorpusPage]

    public init(file: String, pages: [AutomationCorpusPage]) {
        self.file = file
        self.pages = pages
    }
}

public struct AutomationCorpusPage: Codable, Hashable, Sendable {
    public var pageIndex: Int
    public var symbols: [AutomationSymbolLabel]
    public var rooms: [AutomationRoomLabel]
    /// The sheet number as printed, when the sheet has one.
    public var sheetNumber: String?
    public var sheetTitle: String?
    /// The sheet's scale as printed, `"1:100"`.
    public var scale: String?

    public init(
        pageIndex: Int,
        symbols: [AutomationSymbolLabel] = [],
        rooms: [AutomationRoomLabel] = [],
        sheetNumber: String? = nil,
        sheetTitle: String? = nil,
        scale: String? = nil
    ) {
        self.pageIndex = pageIndex
        self.symbols = symbols
        self.rooms = rooms
        self.sheetNumber = sheetNumber
        self.sheetTitle = sheetTitle
        self.scale = scale
    }
}

/// A rectangle in page points, origin bottom-left.
public struct AutomationRect: Codable, Hashable, Sendable {
    public var x: Double
    public var y: Double
    public var width: Double
    public var height: Double

    public init(x: Double, y: Double, width: Double, height: Double) {
        self.x = x
        self.y = y
        self.width = width
        self.height = height
    }
}

public struct AutomationPoint: Codable, Hashable, Sendable {
    public var x: Double
    public var y: Double

    public init(x: Double, y: Double) {
        self.x = x
        self.y = y
    }
}

/// Every instance of one symbol on one page, and the box a person would drag round one of them.
public struct AutomationSymbolLabel: Codable, Hashable, Sendable {
    public var designation: String
    public var exemplarBox: AutomationRect
    /// One point per instance, anywhere inside the instance's extent.
    public var instances: [AutomationPoint]
    /// How far a found position may sit from a labelled one and still be that instance.
    public var matchRadius: Double

    public init(designation: String, exemplarBox: AutomationRect, instances: [AutomationPoint], matchRadius: Double) {
        self.designation = designation
        self.exemplarBox = exemplarBox
        self.instances = instances
        self.matchRadius = matchRadius
    }
}

/// A room a click should trace, closing at most the openings a person would close.
public struct AutomationRoomLabel: Codable, Hashable, Sendable {
    public var name: String
    public var click: AutomationPoint
    /// The room's area in square page points, hand-derived.
    public var area: Double
    /// Openings the trace may propose closing to reach that area.
    public var openings: Int

    public init(name: String, click: AutomationPoint, area: Double, openings: Int) {
        self.name = name
        self.click = click
        self.area = area
        self.openings = openings
    }
}

// MARK: - The synthetic corpus

/// Writes the synthetic automation corpus: three PDFs and their labels, every label derived by
/// hand from the coordinates below.
public enum AutomationSyntheticCorpus {

    /// Writes the corpus into `directory` and returns its manifest (also written as
    /// `automation-corpus.json` beside the drawings).
    public static func write(in directory: URL) throws -> AutomationCorpusManifest {
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        try doorPlan().write(to: directory.appendingPathComponent("synthetic-doors.pdf"))
        try roomPlan().write(to: directory.appendingPathComponent("synthetic-rooms.pdf"))
        try titleBlockSet().write(to: directory.appendingPathComponent("synthetic-sheets.pdf"))
        let manifest = AutomationCorpusManifest(name: "synthetic", drawings: [
            AutomationCorpusDrawing(file: "synthetic-doors.pdf", pages: [doorLabels]),
            AutomationCorpusDrawing(file: "synthetic-rooms.pdf", pages: [roomLabels]),
            AutomationCorpusDrawing(file: "synthetic-sheets.pdf", pages: sheetLabels)
        ])
        try manifest.encoded().write(to: directory.appendingPathComponent("automation-corpus.json"))
        return manifest
    }

    // MARK: Doors on walls, with hatch, stroked text and a dimension chain

    /// Door hinge points. Each door: a 30 pt leaf standing up from the hinge, a quarter-circle
    /// swing of radius 30 from the leaf's tip to the wall, drawn on a wall line through the hinge.
    static let doorHinges: [(Double, Double)] = [
        (100, 500), (220, 500), (340, 500), (460, 500),
        (100, 300), (220, 300), (340, 300), (460, 300)
    ]

    static func door(_ x: Double, _ y: Double) -> String {
        // κ = 0.5523 places a cubic's control points on a circle to within 0.03 %.
        let r = 30.0, k = 0.5523 * r
        return """
        \(x) \(y) m \(x) \(y + r) l S
        \(x) \(y + r) m \(x + k) \(y + r) \(x + r) \(y + k) \(x + r) \(y) c S
        """
    }

    static func doorPlan() -> Data {
        var content = ["0.8 w 0 0 0 RG"]
        // Two long walls the doors are drawn on: 520 pt each, so hinge and swing both touch them.
        for y in [500.0, 300.0] {
            content.append("40 \(y) m 560 \(y) l S")
        }
        for (x, y) in doorHinges { content.append(door(x, y)) }
        // Hatch: 25 parallel short diagonals in 60…160 × 100…180.
        content.append("0.2 w")
        for index in 0..<25 {
            let x = 60.0 + Double(index) * 4
            content.append("\(x) 100 m \(x + 20) 180 l S")
        }
        // Text drawn as strokes: "EL" twice, each letter three or four short strokes.
        content.append("0.5 w")
        for x in [300.0, 330.0] {
            content.append("\(x) 120 m \(x) 140 l S \(x) 140 m \(x + 10) 140 l S \(x) 130 m \(x + 8) 130 l S \(x) 120 m \(x + 10) 120 l S")
            content.append("\(x + 14) 120 m \(x + 14) 140 l S \(x + 14) 120 m \(x + 22) 120 l S")
        }
        // A dimension chain under the lower wall: a line, three ticks, and its figures.
        content.append("40 260 m 560 260 l S 40 255 m 40 265 l S 300 255 m 300 265 l S 560 255 m 560 265 l S")
        content.append("BT /F1 8 Tf 160 264 Td (2600) Tj ET BT /F1 8 Tf 420 264 Td (2600) Tj ET")
        return pdf(pages: [content.joined(separator: "\n")], mediaBox: "0 0 595 842")
    }

    static var doorLabels: AutomationCorpusPage {
        AutomationCorpusPage(pageIndex: 0, symbols: [
            AutomationSymbolLabel(
                designation: "D-12",
                // Round the first door: leaf and swing span 100…130 × 500…530.
                exemplarBox: AutomationRect(x: 97, y: 497, width: 36, height: 36),
                instances: doorHinges.map { AutomationPoint(x: $0.0 + 12, y: $0.1 + 12) },
                matchRadius: 15
            )
        ])
    }

    // MARK: Rooms with door openings, a corridor, and a closed room with a column

    /// Offset of the room plan on the page.
    static let ox = 50.0, oy = 100.0

    static func roomPlan() -> Data {
        func segment(_ x0: Double, _ y0: Double, _ x1: Double, _ y1: Double) -> String {
            "\(ox + x0) \(oy + y0) m \(ox + x1) \(oy + y1) l S"
        }
        let lines = [
            "1 w 0 0 0 RG",
            segment(0, 400, 600, 400),      // top of A and B
            segment(0, 100, 0, 400),        // left wall
            segment(300, 200, 300, 400),    // A | B
            segment(0, 200, 100, 200),      // A's bottom wall, door 100…150
            segment(150, 200, 400, 200),    // shared bottom wall, B's door 400…450
            segment(450, 200, 600, 200),
            segment(0, 100, 600, 100),      // corridor bottom
            segment(600, 100, 600, 400),    // corridor end / C's left wall
            segment(600, 400, 800, 400),    // C
            segment(800, 100, 800, 400),
            segment(600, 100, 800, 100),
            // A column inside C: 680…700 × 240…260.
            segment(680, 240, 700, 240), segment(700, 240, 700, 260),
            segment(700, 260, 680, 260), segment(680, 260, 680, 240)
        ]
        return pdf(pages: [lines.joined(separator: "\n")], mediaBox: "0 0 1191 842")
    }

    static var roomLabels: AutomationCorpusPage {
        func point(_ x: Double, _ y: Double) -> AutomationPoint { AutomationPoint(x: ox + x, y: oy + y) }
        return AutomationCorpusPage(pageIndex: 0, rooms: [
            // 300 × 200 = 60 000 each; the corridor 600 × 100 = 60 000 behind two doors;
            // C 200 × 300 = 60 000 with the column an island inside it.
            AutomationRoomLabel(name: "A", click: point(50, 300), area: 60_000, openings: 1),
            AutomationRoomLabel(name: "B", click: point(450, 300), area: 60_000, openings: 1),
            AutomationRoomLabel(name: "Corridor", click: point(300, 150), area: 60_000, openings: 2),
            AutomationRoomLabel(name: "C", click: point(650, 300), area: 60_000, openings: 0)
        ])
    }

    // MARK: Title blocks, Swedish and English

    static func titleBlockSet() -> Data {
        func text(_ string: String, _ x: Double, _ y: Double, size: Double = 10) -> String {
            "BT /F1 \(size) Tf \(x) \(y) Td (\(string)) Tj ET"
        }
        let frame = "0.5 w 900 20 m 1171 20 l 1171 180 l 900 180 l h S"
        let first = [
            frame,
            text("Ritn.nr: A-101", 910, 60, size: 14),
            text("Benämning", 910, 140),
            text("PLAN 1", 910, 118, size: 12),
            text("Skala 1:100", 910, 30),
            text("DETALJ 3 SKALA 1:5", 60, 780)
        ]
        let second = [
            frame,
            text("Ritn.nr: A-102", 910, 60, size: 14),
            text("Benämning", 910, 140),
            text("PLAN 2", 910, 118, size: 12),
            text("Skala 1:50", 910, 30)
        ]
        let third = [
            frame,
            text("DRAWING NO.", 910, 90),
            text("A-103", 910, 66, size: 14),
            text("TITLE", 1040, 140),
            text("SECTION A-A", 1040, 118, size: 12),
            text("SCALE 1:20", 910, 30)
        ]
        let cover = [text("PROJEKT EXEMPELVÄGEN 12", 400, 420, size: 24)]
        return pdf(
            pages: [cover, first, second, third].map { $0.joined(separator: "\n") },
            mediaBox: "0 0 1191 842"
        )
    }

    static var sheetLabels: [AutomationCorpusPage] {
        [
            AutomationCorpusPage(pageIndex: 0),
            AutomationCorpusPage(pageIndex: 1, sheetNumber: "A-101", sheetTitle: "PLAN 1", scale: "1:100"),
            AutomationCorpusPage(pageIndex: 2, sheetNumber: "A-102", sheetTitle: "PLAN 2", scale: "1:50"),
            AutomationCorpusPage(pageIndex: 3, sheetNumber: "A-103", sheetTitle: "SECTION A-A", scale: "1:20")
        ]
    }

    // MARK: Writing

    /// A PDF with one content stream per page and Helvetica (WinAnsi, so å ä ö print) as `/F1`.
    static func pdf(pages: [String], mediaBox: String) -> Data {
        let kids = pages.indices.map { "\(4 + 2 * $0) 0 R" }.joined(separator: " ")
        var objects: [Data] = [
            Data("<< /Type /Catalog /Pages 2 0 R >>".utf8),
            Data("<< /Type /Pages /Kids [\(kids)] /Count \(pages.count) >>".utf8),
            Data("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>".utf8)
        ]
        for (index, content) in pages.enumerated() {
            objects.append(Data(
                "<< /Type /Page /Parent 2 0 R /MediaBox [\(mediaBox)] /Contents \(5 + 2 * index) 0 R /Resources << /Font << /F1 3 0 R >> >> >>".utf8
            ))
            // WinAnsi bytes, so the Swedish letters are one byte each as the font expects.
            let bytes = content.data(using: .windowsCP1252) ?? Data(content.utf8)
            var stream = Data("<< /Length \(bytes.count) >>\nstream\n".utf8)
            stream.append(bytes)
            stream.append(Data("\nendstream".utf8))
            objects.append(stream)
        }
        var data = Data("%PDF-1.7\n".utf8)
        var offsets: [Int] = []
        for (index, object) in objects.enumerated() {
            offsets.append(data.count)
            data.append(Data("\(index + 1) 0 obj\n".utf8))
            data.append(object)
            data.append(Data("\nendobj\n".utf8))
        }
        let xref = data.count
        data.append(Data("xref\n0 \(objects.count + 1)\n0000000000 65535 f \n".utf8))
        for offset in offsets { data.append(Data(String(format: "%010d 00000 n \n", offset).utf8)) }
        data.append(Data("trailer\n<< /Size \(objects.count + 1) /Root 1 0 R >>\nstartxref\n\(xref)\n%%EOF\n".utf8))
        return data
    }
}
